{
  "rules": [
    "Apply a strong negative bias correction (-15% to -20%) when the model forecasts an upward trend while recent history shows a downtrend and sentiment is neutral or slightly positive.",
    "Reduce forecasted volatility by 40-50% during periods of high uncertainty (sentiment near 0.0) where true outcomes exhibit erratic, non-trending behavior.",
    "Cap the maximum daily gain in forecasts at 1.5x the average historical daily move to prevent overshooting sudden market reversals.",
    "Shift the forecast horizon start point backward by 3-5 days when sentiment history shows a recent spike (0.20) followed by neutralization, indicating delayed reaction.",
    "Apply a mean reversion floor correction: if forecasts exceed the last 18-day average by more than 5%, reduce the trajectory to align with historical volatility bands."
  ]
}
